I use playwright to "buscar "mochila"", async ({ page }) => {
                                  const campo = page.locator(SELECTORES.campoBusqueda).first();

                                  for (let intento = 1; intento <= 3; intento++) {
                                    await campo.click();
                                    await campo.fill(producto);

                                    if ((await campo.inputValue()) !== producto) continue;

                                    await campo.press('Enter');
                                    try {
                                      await page.waitForURL(/[?&]s=/, { timeout: 8000 });
                                      return;
                                    } catch (e) {
                                      // el header se re-renderizó y perdió el input; reintentar
                                      console.warn(`[SearchPage] Intento ${intento}/3 falló para "${producto}"; reintentando`)
                                    }
                                  }

                                  throw new Error(`No se pudo ejecutar la búsqueda de "${producto}" tras 3 intentos`);
                                }

I use playwright to "filtrar por precio entre 500 y 2000", async ({ page }) => {
                                  const campoMinimo = page.locator(SELECTORES.inputPrecioMinimo).first()

                                  // El facet puede venir colapsado: se abre SÓLO si hace falta.
                                  // (isVisible() es una foto instantánea; waitFor sí respeta el timeout.)
                                  const facetAbierto = await campoMinimo
                                    .waitFor({ state: 'visible', timeout: 5000 })
                                    .then(() => true)
                                    .catch(() => false)

                                  if (!facetAbierto) {
                                    await page
                                      .locator(SELECTORES.acordeonPrecio)
                                      .filter({ hasText: SELECTORES.textoAcordeonPrecio })
                                      .first()
                                      .click()
                                    await campoMinimo.waitFor({ state: 'visible', timeout: 10000 })
                                  }

                                  const campoMaximo = page.locator(SELECTORES.inputPrecioMaximo).first()

                                  for (let intento = 1; intento <= INTENTOS_MAXIMOS; intento++) {
                                    const urlAnterior = page.url()

                                    await campoMinimo.fill('')
                                    await campoMinimo.fill(String(minimo))
                                    await campoMinimo.blur()

                                    await campoMaximo.fill('')
                                    await campoMaximo.fill(String(maximo))
                                    await campoMaximo.blur()

                                    const minimoEscrito = await campoMinimo.inputValue()
                                    const maximoEscrito = await campoMaximo.inputValue()

                                    if (minimoEscrito !== String(minimo) || maximoEscrito !== String(maximo)) {
                                      continue
                                    }

                                    const aplicar = campoMinimo
                                      .locator(SELECTORES.facetDePrecio)
                                      .locator(`${SELECTORES.botonAplicarPrecio}:visible`)
                                      .first()

                                    await aplicar.waitFor({ state: 'visible', timeout: 10000 })
                                    await aplicar.click()

                                    await esperarActualizacionDeResultados(page, urlAnterior)
                                    return
                                  }

                                  throw new Error(
                                    `No se pudo fijar el rango de precio ${minimo}-${maximo} tras ${INTENTOS_MAXIMOS} intentos.`
                                  )
                                }

I use playwright to "esperar a que la PLP renderice", async ({ page }) => {
                                  try {
                                    await page.waitForSelector(selector, { state: 'attached', timeout: 20000 })
                                  } catch (e) {
                                    console.warn(`[ResultsPage] PLP no detectada en 20s; continuando. ${e.message}`)
                                    await page.waitForLoadState('domcontentloaded')
                                  }
                                }

I use playwright to "leer el texto de cada tarjeta de producto", async ({ page }) => {
                                  const anclas = await page.locator(SELECTORES.tarjetasProducto).all()
                                  const textos = []

                                  for (const ancla of anclas) {
                                    const contenedor = ancla.locator(CONTENEDOR_DE_TARJETA)

                                    try {
                                      textos.push(await contenedor.innerText({ timeout: 3000 }))
                                    } catch (e) {
                                      // Si la estructura cambia y el contenedor no resuelve, se usa el <a>.
                                      textos.push(await ancla.innerText())
                                    }
                                  }

                                  return textos
                                }
